{
  "items": [
    {
      "name": "Finsupp.weight_eq_zero_iff_eq_zero",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_4} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M]\n  [CanonicallyOrderedAdd M] (w : σ → M) [Finsupp.NonTorsionWeight ℕ w] {f : σ →₀ ℕ}, (Finsupp.weight w) f = 0 ↔ f = 0"
    },
    {
      "name": "Finsupp.add_eq_zero_iff",
      "module_name": "Mathlib.Data.Finsupp.Order",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_3} [inst : AddCommMonoid α] [inst_1 : PartialOrder α] [CanonicallyOrderedAdd α]\n  (f g : ι →₀ α), f + g = 0 ↔ f = 0 ∧ g = 0"
    },
    {
      "name": "Finsupp.degree_eq_zero_iff",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_5} [inst : AddCommMonoid R] [inst_1 : PartialOrder R] [CanonicallyOrderedAdd R]\n  (d : σ →₀ R), Finsupp.degree d = 0 ↔ d = 0"
    },
    {
      "name": "DFinsupp.add_eq_zero_iff",
      "module_name": "Mathlib.Data.DFinsupp.Order",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : (i : ι) → AddCommMonoid (α i)] [inst_1 : (i : ι) → PartialOrder (α i)]\n  [∀ (i : ι), CanonicallyOrderedAdd (α i)] (f g : Π₀ (i : ι), α i), f + g = 0 ↔ f = 0 ∧ g = 0"
    },
    {
      "name": "Finset.sum_eq_zero_iff_of_nonneg",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {N : Type u_5} [inst : AddCommMonoid N] [inst_1 : PartialOrder N] {f : ι → N} {s : Finset ι}\n  [AddLeftMono N], (∀ i ∈ s, 0 ≤ f i) → (∑ i ∈ s, f i = 0 ↔ ∀ i ∈ s, f i = 0)"
    },
    {
      "name": "DFinsupp.sum_eq_zero",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {γ : Type w} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : (i : ι) → Zero (β i)]\n  [inst_2 : (i : ι) → (x : β i) → Decidable (x ≠ 0)] [inst_3 : AddCommMonoid γ] {f : Π₀ (i : ι), β i}\n  {h : (i : ι) → β i → γ}, (∀ (i : ι), h i (f i) = 0) → f.sum h = 0"
    },
    {
      "name": "Finset.sum_eq_zero_iff",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} {s : Finset ι} [inst : AddCommMonoid M] {f : ι → M} [Subsingleton (AddUnits M)],\n  ∑ i ∈ s, f i = 0 ↔ ∀ i ∈ s, f i = 0"
    },
    {
      "name": "ENNReal.tsum_eq_zero",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.ENNReal",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {f : α → ENNReal}, ∑' (i : α), f i = 0 ↔ ∀ (i : α), f i = 0"
    }
  ]
}

